title: $:/plugins/ahanniga/context-menu/ContextListener.js
type: application/javascript
module-type: widget

This widgets implements context menus to tiddlers
\*/

(function () {

    var sanitize = function (string) {
        const map = {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#x27;',
            "/": '&#x2F;',
        };
        const reg = /[&<>"'/]/ig;
        return string.replace(reg, (match) => (map[match]));
    };

    var htmlToElement = function (html) {
        var template = document.createElement('template');
        template.innerHTML = html.trim();
        return template.content.firstChild;
    }

    var parseParameters = function (src) {
        let paramMatcher = /\\parameters\s*\((.*?)\)/;
        let paramMatch = src.match(paramMatcher);
        let parameters = {};
        if (paramMatch && paramMatch.length > 1) {
            paramMatch[1].split(",").forEach(pair => {
                let [key, value] = pair.split(":");
                if (key && value) {
                    parameters[key.trim()] = value.replace(/["']/g, "").trim();
                }
            });

            // Remove the \parameters block from the src
            src = src.replace(paramMatcher, '').trim();
        }

        Object.keys(parameters).forEach(param => {
            let re = new RegExp("<<" + param + ">>", "g");
            src = src.replace(re, parameters[param]);
        });

        return src;
    }

    var Widget = require("$:/core/modules/widgets/widget.js").widget;
    // Reverted to original class name
    // popover="manual" puts the menu in the browser's top layer when it opens, so no story
    // frame or overlay can be drawn over it however high their z-index is. "manual" leaves
    // dismissal to this plugin's own click handler instead of the browser's light dismiss.
    var template = `<div id="contextMenu" class="context-menu" popover="manual" style="display: none; z-index: 10000;"></div>`;

    // The one place the menu is placed. The popover UA box (inset 0 with auto margins, which would
    // centre the menu) is cleared by #contextMenu[popover] in styles.css, so nothing here touches
    // "inset": it is a shorthand for left/top, and writing it after the coordinates is what once
    // dropped the fixed menu to its static position instead of the pointer.
    var placeMenu = function (menu, x, y) {
        menu.style.display = "block";
        var width = menu.offsetWidth;
        var height = menu.offsetHeight;
        var left = x;
        var top = y;
        // Flip left/up where the menu would overflow the window, keeping it on screen.
        if (left + width > window.innerWidth) {
            left = left - width;
            if (left < 0) left = window.innerWidth - width - 5;
            if (left < 0) left = 5;
        }
        if (top + height > window.innerHeight) {
            top = top - height;
            if (top < 0) top = window.innerHeight - height - 5;
            if (top < 0) top = 5;
        }
        if (menu.showPopover && !menu.matches(":popover-open")) {
            try { menu.showPopover(); } catch (e) {}
        }
        menu.style.left = left + "px";
        menu.style.top = top + "px";
    };

    var closeMenu = function (menu) {
        if (menu.hidePopover && menu.matches(":popover-open")) {
            try { menu.hidePopover(); } catch (e) {}
        }
        menu.style.display = "none";
    };

    var ContextListener = function (parseTreeNode, options) {
        this.initialise(parseTreeNode, options);
    };

    ContextListener.prototype = new Widget();

    ContextListener.prototype.render = function (parent, nextSibling) {
        this.parentDomNode = parent;
        var self = this;
        // Guard: only attach once to prevent stacking listeners across layout switches.
        if (!ContextListener._listenerAttached) {
            ContextListener._contextMenuHandler = function (event) { self.contextmenu.call(self, event); };
            ContextListener._clickHandler = function () { self.hideMenu.call(self); };
            document.addEventListener("contextmenu", ContextListener._contextMenuHandler);
            document.addEventListener("click", ContextListener._clickHandler);
            ContextListener._listenerAttached = true;
        }
    };

    ContextListener.prototype.contextmenu = function (event) {
        var self = this;
        var menu = document.getElementById("contextMenu");

        if (getSelection().toString().trim().length > 0) {
            // User has selected text, so don't trigger this menu
            return true;
        }

        // Skip when the whiteboard layout is active - TLDraw manages its own context menu.
        if (event.target && event.target.closest && event.target.closest(".tw-whiteboard-layout-container")) {
            return true;
        }

        // Allow default context menu for unieditor elements to use spell check
        if (event.target && event.target.closest && event.target.closest(".unieditor__textarea")) {
            return true;
        }

        if (menu == null) {
            this.document.body.appendChild(htmlToElement(template));
            menu = document.getElementById("contextMenu");
            menu.addEventListener("click", function (event) { self.menuClicked.call(self, event) });
        }
        menu.innerHTML = "";

        // Reverted to UL structure
        var menuHtml = ["<ul>"];
        var titles = $tw.wiki.getTiddlersWithTag("$:/tags/tiddlercontextmenu");
        var label, action, icon, tid, targ, text, separator, paramFilter, customParam;

        // Check if we can find a closer tiddler title (e.g. Streams node)
        // Streams uses data-node-title, standard TW uses data-tiddler-title
        var closestTiddler = event.target.closest("[data-tiddler-title], [data-node-title]");

        // Priority 1: Check if we clicked on a link directly
        var link = event.target.closest(".tc-tiddlylink");
        if (link) {
            var title = link.getAttribute("data-tiddler-title");
            if (!title && link.hasAttribute("href")) {
                var href = link.getAttribute("href");
                if (href.startsWith("#")) {
                    title = decodeURIComponent(href.substring(1));
                }
            }
            if (title) {
                targ = title;
            }
        }

        // Priority 2: Fallback to container if no link found
        if (!targ) {
            if (closestTiddler) {
                // Prioritize node-title if it exists (it's likely the specific row)
                targ = closestTiddler.getAttribute("data-node-title") || closestTiddler.getAttribute("data-tiddler-title");
            }
        }

        // If still no target, return true to allow default browser context menu
        if (!targ) {
            return true;
        }

        for (var a = 0; a < titles.length; a++) {
            tid = $tw.wiki.getTiddler(titles[a]);
            text = sanitize(tid.getFieldString("text", "hide"));

            if (text !== "show") {
                continue;
            }

            label = tid.getFieldString("caption", "Unlabelled Option");
            if (label.indexOf("{{") !== -1 || label.indexOf("<<") !== -1) {
                label = $tw.wiki.renderText("text/plain", "text/vnd.tiddlywiki", label, {
                    parseAsInline: true,
                    variables: { currentTiddler: targ }
                });
            }
            label = sanitize(label);
            action = sanitize(tid.getFieldString("tm-message", "tm-dummy"));
            icon = $tw.wiki.getTiddlerText(tid.getFieldString("icon", "$:/core/images/blank"));
            if (icon) {
                icon = parseParameters(icon);
            } else {
                icon = "";
            }
            // Use original separator class
            separator = tid.fields["separate-after"] === undefined ? "" : "menu-separator";

            // --- PATCH START ---
            // Check for param-filter and pre-calculate the text to copy
            paramFilter = tid.getFieldString("param-filter");
            customParam = "";
            if (paramFilter) {
                // TiddlyWiki filterTiddlers often fails variable resolution (<currentTiddler>) when called outside a real Widget DOM tree.
                // We bypass this entirely by text-replacing <currentTiddler> with our known target row title.
                var resolvedFilter = paramFilter.replace(/<currentTiddler>/g, "[" + targ + "]");

                var iterator = function (callback) {
                    callback($tw.wiki.getTiddler(targ), targ);
                };

                var results = $tw.wiki.filterTiddlers(resolvedFilter, null, iterator);
                if (results.length > 0) {
                    customParam = sanitize(results.join('\n'));
                }
            }
            // --- PATCH END ---

            // Reverted to LI structure. Note icons will be reversed via CSS.
            menuHtml.push(`<li class="${separator}"><a action="${action}" targ="${targ}" data-custom-param="${customParam}" href="#!">${icon} ${label}</a></li>`);
        }

        menuHtml.push("</ul>");
        menu.append(htmlToElement(menuHtml.join("")))

        if (menu.style.display == "block") {
            this.hideMenu();
        } else {
            // --- HIGHLIGHT PATCH START ---
            document.querySelectorAll(".lithic-context-menu-active, .lithic-context-menu-active-children").forEach(function (el) {
                el.classList.remove("lithic-context-menu-active", "lithic-context-menu-active-children");
            });

            if (link) {
                // If a specific link was clicked, only highlight the link
                link.classList.add("lithic-context-menu-active");
            } else if (closestTiddler) {
                // Otherwise, check if it's a stream node
                var droppable = closestTiddler.closest(".stream-droppable");
                if (droppable) {
                    droppable.classList.add("lithic-context-menu-active");
                    if (droppable.nextElementSibling && droppable.nextElementSibling.classList.contains("stream-row-children")) {
                        droppable.nextElementSibling.classList.add("lithic-context-menu-active-children");
                    }
                } else {
                    closestTiddler.classList.add("lithic-context-menu-active");
                }
            }
            // --- HIGHLIGHT PATCH END ---

            placeMenu(menu, event.clientX, event.clientY);
        }

        event.preventDefault();
        return false;
    };

    ContextListener.prototype.menuClicked = function (event) {
        var targetStart = event.target;
        var targetAction = targetStart.closest("[action]");

        if (!targetAction) {
            return false;
        }

        var action = targetAction.getAttribute("action");
        var targ = targetAction.getAttribute("targ");
        // Retrieve our custom param
        var customParam = targetAction.getAttribute("data-custom-param");

        var tid, stid, state, text, ptid;
        this.hideMenu();

        switch (action) {
            case "tm-fold-tiddler":
                stid = `$:/state/folded/${targ}`;
                state = $tw.wiki.getTiddlerText(stid, "show") === "show" ? "hide" : "show";
                $tw.wiki.setText(stid, "text", null, state);
                break;
            case "tm-copy-to-clipboard":
                // --- PATCH START ---
                // If we have a custom param, use it. Otherwise default to body text.
                if (customParam && customParam !== "") {
                    text = customParam;
                } else {
                    text = $tw.wiki.getTiddlerText(targ);
                }
                // --- PATCH END ---
                this.dispatchEvent({ type: action, param: text });
                break;
            case "tm-print":
                this.dispatchEvent({ type: action, event: event });
                break;
            case "lithic-copy-share-url":
                var exportData = [];
                var filter = "[[" + targ + "]] [[" + targ + "]get-stream-nodes[]]";
                var tiddlerTitles = $tw.wiki.filterTiddlers(filter);
                var baseTarg = targ;
                for (var t = 0; t < tiddlerTitles.length; t++) {
                    var tidObj = $tw.wiki.getTiddler(tiddlerTitles[t]);
                    if (tidObj) {
                        var isParent = (t === 0);
                        var newTags = (tidObj.fields.tags || []).slice();

                        // Parse and Wikify to handle transclusions (flattened to plain text)
                        var flattenedText = tidObj.fields.text || "";
                        if (flattenedText.indexOf("{{") !== -1) {
                            // Render transclusions as plain text using the core wikifier
                            // We use text/plain output so we don't carry over HTML structure, just the raw content resolved.
                            flattenedText = $tw.wiki.renderText("text/plain", "text/vnd.tiddlywiki", flattenedText, {
                                parseAsInline: false,
                                variables: { currentTiddler: tidObj.fields.title }
                            });
                        }

                        tidObj = new $tw.Tiddler(tidObj, {
                            tags: newTags,
                            text: flattenedText
                        });

                        var fields = {};
                        for (var field in tidObj.fields) {
                            fields[field] = tidObj.getFieldString(field);
                        }
                        exportData.push(fields);
                    }
                }
                var jsonPayload = JSON.stringify(exportData);
                var encodedPayload = btoa(unescape(encodeURIComponent(jsonPayload)));
                var shareUrl = "https://lithic.uk/?json=" + encodedPayload;

                // --- RICH CLIPBOARD IMPLEMENTATION START ---
                var linkText = targ + " on Lithic.uk";
                var htmlContent = '<a href="' + shareUrl + '">' + linkText + '</a>';
                var plainContent = shareUrl;

                if (navigator.clipboard && window.ClipboardItem) {
                    var htmlBlob = new Blob([htmlContent], { type: "text/html" });
                    var plainBlob = new Blob([plainContent], { type: "text/plain" });
                    var item = new ClipboardItem({
                        "text/html": htmlBlob,
                        "text/plain": plainBlob
                    });

                    var widgetNode = this;
                    navigator.clipboard.write([item]).then(function () {
                        // Check URL length and notify if too long
                        if (shareUrl.length > 2000) {
                            var alertTitle = "$:/temp/alerts/ShareUrlTooLong";
                            var warningText = "Warning: Share URL is " + shareUrl.length + " chars. ";
                            if (shareUrl.length > 8192) {
                                warningText += "It exceeds 8KB and WILL be rejected by most web servers (414 URI Too Long).";
                            } else {
                                warningText += "It exceeds 2KB and may be truncated by chat apps like Discord.";
                            }

                            $tw.wiki.addTiddler({
                                title: alertTitle,
                                text: warningText,
                                component: "Lithic Share"
                            });
                            widgetNode.dispatchEvent({ type: "tm-notify", param: alertTitle });
                        } else {
                            // Trigger standard TW visual notification
                            widgetNode.dispatchEvent({ type: "tm-notify", param: "$:/core/ui/Notifications/CopiedToClipboard" });
                        }
                    }).catch(function (err) {
                        // Fallback if writing multiple blob types fails due to strict OS/Browser security
                        widgetNode.dispatchEvent({ type: "tm-copy-to-clipboard", param: plainContent });
                    });
                } else {
                    // Fallback for older browsers or non-secure contexts (HTTP vs HTTPS)
                    this.dispatchEvent({ type: "tm-copy-to-clipboard", param: plainContent });
                }
                // --- RICH CLIPBOARD IMPLEMENTATION END ---
                break;
            case "tm-unfold-all-tiddlers":
                this.dispatchEvent({ type: action, param: targ, foldedStatePrefix: "$:/state/folded/" });
                break;
            case "sp-print-river":
                var curEntries = [];
                ptid = $tw.wiki.getTiddler("$:/PrintList");
                if (ptid !== undefined) {
                    var list = ptid.getFieldList("list");
                    if (Array.isArray(list) && list.indexOf(targ) < 0) {
                        for (a = 0; a < list.length; a++) {
                            curEntries.push(list[a]);
                        }
                    }
                }
                curEntries.push(targ);
                $tw.wiki.setText("$:/PrintList", "list", 0, curEntries);
                $tw.rootWidget.dispatchEvent({ type: 'tm-open-window', param: '$:/plugins/BTC/PrintRiver/ui/Templates/PrintRiver' });
                break;
            case "tm-new-here":
                this.dispatchEvent({ type: "tm-new-tiddler", paramObject: { tags: targ } });
                break;
            default:
                this.dispatchEvent({ type: action, param: targ });
        }

        event.preventDefault();
        return false;
    };

    ContextListener.prototype.refresh = function (changedTiddlers) {
        return false;
    };

    ContextListener.prototype.hideMenu = function () {
        var menu = document.getElementById("contextMenu");
        if (menu != null) {
            closeMenu(menu);
        }
        // --- HIGHLIGHT PATCH START ---
        document.querySelectorAll(".lithic-context-menu-active, .lithic-context-menu-active-children").forEach(function (el) {
            el.classList.remove("lithic-context-menu-active", "lithic-context-menu-active-children");
        });
        // --- HIGHLIGHT PATCH END ---
    };

    exports.contextMenu = ContextListener;

})();"},"$:/plugins/ahanniga/context-menu/styles.css":{"title":"$:/plugins/ahanniga/context-menu/styles.css","type":"text/css","tags":"$:/tags/Stylesheet","text":"/* Menu colours from the lithic contrast core (--lithic-c-menu-*): items,
   icons and hover pairs are WCAG-checked against the live palette, so the
   menu is readable on light and dark palettes alike. */

.context-menu {
	position: fixed;
	min-width: 180px;
	max-width: 240px;
	z-index: 10000;
	display: flex;
	flex-direction: column;
	background-color: var(--lithic-c-menu-bg);
	border-radius: 6px;
	box-shadow: rgba(0, 0, 0, 0.40) 0px 2px 20px;
	padding: 12px 0;
	border: 1px solid var(--lithic-c-menu-border);
	font-family: "Segoe UI", Roboto, Helvetica, Arial;
	font-size: 13px;
	margin-top: 4px;
}

.context-menu > ul {
	list-style: none;
	padding: 0;
	margin: 0;
}

.context-menu > ul > li > a {
	font: inherit;
	border: 0;
	padding: 4px 18px;
	width: 100%;
	display: flex;
	align-items: center;
	justify-content: space-between;
	flex-direction: row-reverse;
	position: relative;
	text-decoration: unset;
	color: var(--lithic-c-menu-fg) !important;
	fill: var(--lithic-c-menu-fg) !important;
	line-height: 24px;
	font-weight: normal;
	transition: none;
	cursor: default;
}

.context-menu > ul > li > a:hover {
	background: var(--lithic-c-menu-hover-bg);
	color: var(--lithic-c-menu-hover-fg);
	fill: var(--lithic-c-menu-hover-fg);
}

.context-menu > ul > li > a:hover > svg {
	color: var(--lithic-c-menu-hover-fg);
	fill: var(--lithic-c-menu-hover-fg);
}

.context-menu > ul > li > a > i {
	padding-left: 10px;
}

.context-menu > ul > li > a > svg {
	color: var(--lithic-c-menu-muted) !important;
	fill: var(--lithic-c-menu-muted) !important;
	width: 13px;
	margin-left: 16px;
	margin-right: 0;
	height: 13px;
}

ul .menu-separator {
	border-bottom: 1px solid var(--lithic-c-menu-border);
	margin-bottom: 6px;
	margin-top: 6px;
	padding-bottom: 0;
}

/* The menu is promoted into the browser's top layer (popover="manual" on #contextMenu, set
   in ContextListener.js), so nothing on the page can be drawn over it, whatever z-index it
   uses. Only the parts of a popover's UA box that the rule above does not already override
   are reset here; the menu's own chrome comes from .context-menu. */
#contextMenu[popover] {
	inset: auto;
	margin: 0;
	overflow: visible;
}

/* The menu pops in the way every other drop-down in Lithic does. The Notebook theme
   animates .tc-drop-down on its own, which is why the streams node menu already fades
   in, but this menu is its own element (#contextMenu, classed .context-menu) and never
   matches that selector, so the same frames are declared here. The keyframes name is
   local so the menu does not depend on the theme in use, and it uses the theme's exact
   stopping points (0.8, a 1.03 overshoot, settle at 1) so the two menus feel the same.
   Forwards is deliberately omitted: a lingering transform would leave a stacking
   context on an element the popover already lifts above the page, and the settled
   scale(1) is what the menu looks like without any transform at all. The animation
   replays on every open because closeMenu sets display: none, which restarts it. */
@keyframes lithic-context-menu-pop {
	0% {
		transform: scale(0.8);
		opacity: 0;
	}

	80% {
		transform: scale(1.03);
		opacity: 1;
	}

	100% {
		transform: scale(1);
		opacity: 1;
	}
}

#contextMenu {
	animation: lithic-context-menu-pop 0.15s ease-in;
}

/* Context Menu Highlight Patch - applies when right-clicking a stream node or link.
   Palette-aware and live: the notify-bg/-fg contrast roles are derived from the SAME
   palette fields as the streams patch's own highlight band
   ($:/lithic/streams/styles/ctx-preview), so the two can never drift -- on the
